function findPropertyDescriptor(obj: object, key: string): PropertyDescriptor | undefined {
  let cur = obj;
  while (cur) {
    const desc = Object.getOwnPropertyDescriptor(cur, key);
    if (desc) return desc;
    cur = Object.getPrototypeOf(cur);
  }
  return undefined;
}
