function installProperty(camera, key, state) {
 const desc = key==='radius'? state.radius : state.yaw;
 if (!desc || !desc.configurable) return false;
 const getter = desc.get;
 const setter = desc.set;
 const isAccessor = getter || setter;
 if (!isAccessor) {
   const current = typeof desc.value === 'number' ? desc.value : undefined;
   state[key] = current; // fallbackValue
 }
 Object.defineProperty(camera, key, {
   configurable: true,
   enumerable: true,
   get() {
     return read(camera, state, key);
   },
   set(value) {
     write(camera, state, key, value);
   }
 });
