  limits: GeospatialLimits;
  radiusDescriptor?: PropertyDescriptor;
  yawDescriptor?: PropertyDescriptor;
  radiusValue: number;
  yawValue: number;
  wrappedRadius: boolean;
  wrappedYaw: boolean;
  applying: boolean;
