const states = new WeakMap<GeospatialCamera, LimitsState>();

function finiteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function normalizeYaw(angle: number): number {
  if (!finiteNumber(angle)) return 0;
  let wrapped = angle % TWO_PI;
  if (wrapped >= PI) wrapped -= TWO_PI;
  else if (wrapped < -PI) wrapped += TWO_PI;
  return wrapped;
}

function circularDistance(a: number, b: number): number {
  const d = Math.abs(normalizeYaw(a - b));
  return d;
}

